(async () => {
  const { readFileSync } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  const content = readFileSync(inputPath, 'utf8');
  globalThis.csvContent = content;
})();

(async () => {
  const mod = await import('papaparse');
  const Papa = mod.default || mod;
  if (typeof Papa.parse !== 'function') throw new Error('papaparse: required method parse not in exports');
  const result = Papa.parse(globalThis.csvContent, { header: true });
  globalThis.parsed = result.data;
})();
